def generate_cache_key(user_id, data_template):
    """Generates a unique key for caching."""
    base_str = f"{user_id}:{data_template}"
    return hashlib.md5(base_str.encode()).hexdigest()

def check_cache_exists(cache, key):
    return key in cache

def remove_key(cache, key):
    if key in cache:
        del cache[key]
        return True
    return False

