def convert_text(content):
    # Shift-JIS bytes to UTF-8 string
    return content.decode('shift_jis').encode('utf-8')

def main():
    with open('input.txt', 'rb') as f:
        data = f.read()
        print(convert_text(data).decode('utf-8'))

if __name__ == '__main__':
    main()

